siness_id" id="registration-business-id" value=""><label class="wide" id="registration-new-name-wrap" hidden>Nombre legal o comercial del negocio que falta<input name="business_name" id="registration-new-name" maxlength="180" autocomplete="organization"><small>Completa los datos del negocio a continuación. Revisaremos la solicitud antes de publicarla.</small></label></fieldset><?php require __DIR__.'/new-business-fields.php'; ?><fieldset id="registration-continuation" hidden disabled><legend>2. Identificación, suscripción y solicitud</legend><?php require __DIR__.'/holder-fields.php';require __DIR__.'/subscription-choice.php'; ?><fieldset class="operator-registration" data-operator-prices="<?=esc(json_encode($addonPrices))?>"><legend>Visibilidad adicional</legend><?php require __DIR__.'/operator-addon-choice.php'; ?><p data-operator-registration-total role="status"></p></fieldset><fieldset><legend>Tu relación con el negocio y los soportes</legend><div class="destination-form-grid"><label>Tu nombre<input name="display_name" maxlength="180" autocomplete="name" required value="<?=esc($currentAccount['display_name']??$_POST['display_name']??'')?>" <?=$currentAccount?'readonly':''?>></label><label>Correo de contacto<input type="email" name="email" maxlength="254" autocomplete="email" required value="<?=esc($currentAccount['email']??$_POST['email']??'')?>" <?=$currentAccount?'readonly':''?>></label><label>Teléfono (opcional)<input type="tel" name="phone" maxlength="40" autocomplete="tel" value="<?=esc($_POST['phone']??'')?>"></label><label>Tu relación<select name="relationship_code" id="registration-relationship" required><option value="">Selecciona</option><option value="owner">Soy propietario/a</option><option value="legal_representative">Soy representante legal</option><option value="authorized_administrator">Soy administrador/a autorizado/a</option></select></label><label class="wide">Documento de identidad · PDF, JPG, PNG o WebP · máximo 8 MB<input type="file" name="