tud'?></button></fieldset></form><?php if(!$currentAccount):?><p>¿Ya tienes cuenta? <a href="<?=esc(site_path('/negocios/acceso/'))?>">Inicia sesión</a></p><?php endif ?></section></main><?php require __DIR__.'/../_business-map-dialog.php'; ?><script src="/assets/leaflet.js"></script><script src="/assets/admin-business-location.js?v=17" defer></script><script src="<?=esc(site_path('/assets/business-registration.js?v=7'))?>" defer></script><script src="/assets/account-files.js?v=1" defer></script><script src="/assets/operator-addon-registration.js?v=3" defer></script></body></html>
